// --- 防拷貝與防 F12 開發者工具防護 ---

// 1. 禁用滑鼠右鍵選單
document.addEventListener('contextmenu', function (event) {
    event.preventDefault(); // 阻止預設的右鍵選單彈出
});

// 2. 禁用特定鍵盤快捷鍵
document.addEventListener('keydown', function (event) {
    // 阻擋 F12
    if (event.key === 'F12' || event.keyCode === 123) {
        event.preventDefault();
        return false;
    }
    
    // 阻擋 Ctrl+Shift+I (開發者工具) 與 Ctrl+Shift+J (主控台)
    if (event.ctrlKey && event.shiftKey && (event.key === 'I' || event.key === 'i' || event.key === 'J' || event.key === 'j')) {
        event.preventDefault();
        return false;
    }
    
    // 阻擋 Ctrl+U (檢視原始碼) 與 Ctrl+C (複製)
    if (event.ctrlKey && (event.key === 'U' || event.key === 'u' || event.key === 'C' || event.key === 'c')) {
        event.preventDefault();
        return false;
    }
});